var EXTRA=[{"dot": "gray", "j": "J ISAKOS", "h": "Mini-impianti metallici su misura per difetti condrali del femore: esiti a medio termine", "v": "Serie retrospettiva con impianto Episealer su lesioni focali del femore distale quando la riparazione biologica non è praticabile: miglioramento dei punteggi in entrambi i gruppi, sopravvivenza giudicata accettabile; è protesica parziale, non cartilagine biologica.", "pmid": "42860156", "doi": "10.1016/j.jisako.2026.101234", "temi": ["cartilagine", "mini-impianti", "difetto osteocondrale"]}, {"dot": "gray", "j": "J Orthop Sci", "h": "Un punteggio per riconoscere il menisco laterale ipermobile prima dell'artroscopia", "v": "Modello diagnostico retrospettivo, validato solo internamente: gli autori stessi chiedono una validazione esterna prima di usarlo. Tocca la lesione che la risonanza spesso non vede.", "pmid": "42859119", "doi": "10.1016/j.jos.2026.09.016", "temi": ["menisco laterale", "diagnosi", "ipermobilità"]}, {"dot": "gray", "j": "J Robot Surg", "h": "TKA robotica con allineamento funzionale: la rotazione femorale segue la tensione mediale", "v": "Osservazione di un solo chirurgo sui ginocchi varo: più stretto il compartimento mediale in flessione, più rotazione femorale scelta; gli autori precisano che l'equazione descrive le sue scelte e non è una regola validata.", "pmid": "42860454", "doi": "10.1007/s11701-026-04037-6", "temi": ["protesi totale", "robotica", "allineamento funzionale"]}, {"dot": "gray", "j": "Br J Sports Med", "h": "Registro nazionale svedese: ritorno allo sport dopo LCA in atleti con attività pre-infortunio alta", "v": "Coorte di registro su tutto il paese; su PubMed l'abstract non è disponibile: titolo e rivista confermati, contenuto non verificato.", "pmid": "42864256", "doi": "10.1136/bjsports-2025-111497", "temi": ["LCA", "ritorno allo sport", "registro"]}, {"dot": "gray", "j": "BMC Anesthesiol", "h": "Blocco 4-in-1, femorale e canale adduttorio dopo LCA: analgesia sovrapponibile", "v": "RCT a tre bracci con registrazione retrospettiva e un'analisi di non inferiorità esplorativa e post hoc: nessuna differenza nel consumo di oppioidi, studio piccolo.", "pmid": "42850592", "doi": "10.1186/s12871-026-04109-y", "temi": ["LCA", "anestesia", "blocco nervoso"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Semitendinoso rinforzato con scaffold BioBrace nel LCA tutto-dentro", "v": "Nota tecnica per innesti singoli sottili: lo scaffold è proposto come rinforzo meccanico e biologico; nessun paziente, nessun confronto, prodotto commerciale.", "pmid": "42857523", "doi": "10.1002/atn2.70292", "temi": ["LCA", "hamstring", "scaffold"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Mezzo tendine peroneo lungo prelevato sotto il malleolo per il LCA", "v": "Nota tecnica egiziana: la via sottomalleolare dovrebbe dare lunghezza sufficiente senza i problemi dell'incisione retromalleolare; nessun dato clinico.", "pmid": "42856834", "doi": "10.1002/atn2.70309", "temi": ["LCA", "peroneo lungo", "innesto alternativo"]}, {"dot": "gray", "j": "J Exp Orthop", "h": "Il ginocchio che punta all'interno: un angolo misurato alla TC funzionale", "v": "Studio diagnostico su una grande serie di TC bilaterali per dolore anteriore o instabilità rotulea: la misura è riproducibile; soglie normali e rilevanza clinica non ancora definite.", "pmid": "42861179", "doi": "10.1002/jeo2.70938", "temi": ["rotula", "torsione", "TC"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Difetti osteocondrali della troclea: scaffold impiantato tutto in artroscopia", "v": "Nota tecnica su uno scaffold osteocondrale in aragonite già usato per mini-artrotomia; nessun paziente né esito, solo la tecnica e i suoi trucchi.", "pmid": "42852391", "doi": "10.1002/atn2.70306", "temi": ["cartilagine", "troclea", "scaffold"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Fissazione dell'avulsione del LCP: tre modifiche per lavorare sicuri dietro il ginocchio", "v": "Nota tecnica da Xi'an sulla sicurezza della via posteriore, vicina al fascio neurovascolare popliteo: modifiche con strumenti standard; nessun paziente.", "pmid": "42857546", "doi": "10.1002/atn2.70340", "temi": ["LCP", "avulsione", "via posteriore"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Patella alta nello scheletro immaturo: imbricazione del tendine rotuleo a doppia fila", "v": "Nota tecnica che evita l'osteotomia della tuberosità nelle fisi aperte; nessun paziente né esito.", "pmid": "42857235", "doi": "10.1002/atn2.70288", "temi": ["rotula", "patella alta", "adolescente"]}];
var SCOPERTE=[{"t": "Un impianto di ginocchio che produce da sé l'energia per misurare il carico", "v": "Bioingegneria: sei trasduttori in PVDF nel vassoio tibiale di una protesi totale ricavano energia dal carico del cammino e, con una rete neurale, riconoscono otto attività. Vale la deviazione perché mostra la strada degli impianti intelligenti senza batteria; resta a banco, senza pazienti.", "pmid": "42836218", "doi": "10.1016/j.nanoen.2026.112400", "temi": ["bioingegneria", "impianto intelligente", "protesi totale"]}, {"t": "Sensori sulle gambe riconoscono un vecchio infortunio al ginocchio, ma con molti limiti", "v": "Intelligenza artificiale su sensori inerziali (Monaco, con Basilea): prova di concetto su 90 studenti di scienze motorie, alta specificità e sensibilità modesta, modello instabile fra le diverse validazioni. Vale la deviazione perché mostra come potrebbe essere la sorveglianza fuori dal laboratorio e quanto è lontana.", "pmid": "42809372", "doi": "10.1002/ksa.70631", "temi": ["intelligenza artificiale", "sensori", "infortunio precedente"]}, {"t": "Cerniera rotante o articolazione a sfera: la geometria decide l'usura nelle protesi vincolate", "v": "Studio agli elementi finiti da Tianjin su due protesi altamente vincolate: la sfera dà più libertà di rotazione ma più usura del polietilene per lo scorrimento multidirezionale. Vale la deviazione perché è il ragionamento di progetto dietro i vincoli, lontano dalla tua pratica. Solo simulazione.", "pmid": "42846074", "doi": "10.3389/fbioe.2026.1942105", "temi": ["protesi vincolata", "usura", "elementi finiti"]}];
var SOC={"1": {"video": "Sutura della radice del menisco: chi ha avuto sintomi improvvisi sta meglio a due anni. Lo mostra uno studio su 49 operati (J Exp Orthop, ottobre 2026).\n\nI punteggi sono più alti dopo un esordio improvviso (73 contro 67 su 100), il menisco a un anno è meno spostato e l'artrosi è progredita in 1 caso su 28 contro 8 su 21. La guarigione alla risonanza è simile, e quasi tutti hanno avuto un miglioramento rilevante.\n\nIl limite: un solo chirurgo, dati ricostruiti dalle cartelle, differenza di spostamento di mezzo millimetro di significato incerto.\nFonte: PubMed, PMID 42857476.", "linkedin": "Radice posteriore del menisco mediale, pull-out transtibiale: l'esordio acuto si associa a IKDC finale 73,0 contro 67,0 (p=0,02) e a meno progressione di Kellgren-Lawrence (1/28 contro 8/21) rispetto all'insidioso. Coorte retrospettiva monocentrica, 49 pazienti, J Exp Orthop, ottobre 2026.\n\nEstrusione a un anno 3,3 contro 3,9 mm (differenza 0,4 mm, IC 95% 0,1-0,7), aggiustata -0,32 mm (IC 95% da -0,55 a -0,08); guarigione alla RM senza differenza (24/28 contro 16/21 completa, p=0,47); MCID raggiunta da oltre il 95% in entrambi i gruppi.\n\nLimiti: un chirurgo, esordio ricostruito dalle cartelle, nove eventi di progressione (OR aggiustato 0,02; IC 95% 0,001-0,35, instabile), rilevanza clinica dei 0,4 mm incerta.\nFonte: PubMed, PMID 42857476.", "instagram": "Sutura della radice del menisco: sintomi improvvisi, risultati più alti a due anni.\n49 operati: punteggi 73 contro 67, menisco meno spostato a un anno, guarigione simile.\nStudio di un solo chirurgo, differenze piccole.\nFonte: PubMed, PMID 42857476.", "pazienti": "Sutura della radice del menisco: buoni risultati sia dopo un esordio improvviso sia dopo uno graduale.\n\nIn 49 persone operate, chi aveva avuto sintomi di colpo ha ottenuto punteggi un po' più alti e un'artrosi meno avanzata dopo un anno; quasi tutti sono migliorati.\n\nStudio piccolo, di un solo ospedale: la decisione si prende con il chirurgo.\nFonte: PubMed, PMID 42857476."}};
var SOCV={"1": {"video": {"chir": ["Radice del menisco mediale dopo pull-out transtibiale: l'esordio acuto precede risultati migliori, IKDC mediano 73,0 contro 67,0 (p=0,02). Coorte retrospettiva di un chirurgo, J Exp Orthop, ottobre 2026.", "49 pazienti, minimo 24 mesi: progressione di Kellgren-Lawrence 1 su 28 contro 8 su 21 (p<0,01), estrusione a un anno 3,3 contro 3,9 mm (differenza 0,4 mm, IC 95% 0,1-0,7), guarigione alla risonanza sovrapponibile, MCID raggiunta da oltre il 95% in entrambi i gruppi.", "Limiti: retrospettivo, esordio ricostruito dalle cartelle, nove eventi di progressione che rendono instabile l'OR aggiustato, differenza di estrusione di mezzo millimetro senza soglia clinica.\nFonte: PubMed, PMID 42857476."], "misto": ["Sutura della radice del menisco: chi ha avuto sintomi improvvisi sta meglio a due anni. Lo mostra uno studio su 49 operati (J Exp Orthop, ottobre 2026).", "I punteggi sono più alti dopo un esordio improvviso (73 contro 67 su 100), il menisco a un anno è meno spostato e l'artrosi è progredita in 1 caso su 28 contro 8 su 21. La guarigione alla risonanza è simile, e quasi tutti hanno avuto un miglioramento rilevante.", "Il limite: un solo chirurgo, dati ricostruiti dalle cartelle, differenza di spostamento di mezzo millimetro di significato incerto.\nFonte: PubMed, PMID 42857476."], "pazienti": ["Sutura della radice del menisco: i risultati sono buoni con sintomi improvvisi come con sintomi graduali.", "In uno studio su 49 persone operate, quasi tutte sono migliorate in modo importante a due anni. Chi aveva avuto sintomi di colpo ha ottenuto punteggi un po' più alti e, dopo un anno, un'artrosi meno avanzata.", "Lo studio è piccolo e di un solo ospedale: l'indicazione all'intervento si valuta con il chirurgo.\nFonte: PubMed, PMID 42857476."]}, "linkedin": {"chir": ["Radice posteriore del menisco mediale, pull-out transtibiale: l'esordio acuto si associa a IKDC finale 73,0 contro 67,0 (p=0,02) e a meno progressione di Kellgren-Lawrence (1/28 contro 8/21) rispetto all'insidioso. Coorte retrospettiva monocentrica, 49 pazienti, J Exp Orthop, ottobre 2026.", "Estrusione a un anno 3,3 contro 3,9 mm (differenza 0,4 mm, IC 95% 0,1-0,7), aggiustata -0,32 mm (IC 95% da -0,55 a -0,08); guarigione alla RM senza differenza (24/28 contro 16/21 completa, p=0,47); MCID raggiunta da oltre il 95% in entrambi i gruppi.", "Limiti: un chirurgo, esordio ricostruito dalle cartelle, nove eventi di progressione (OR aggiustato 0,02; IC 95% 0,001-0,35, instabile), rilevanza clinica dei 0,4 mm incerta.\nFonte: PubMed, PMID 42857476."], "misto": ["Sutura della radice del menisco interno: con sintomi comparsi di colpo i risultati a due anni sono più alti (IKDC 73 contro 67) e l'artrosi progredisce meno a un anno.", "Studio su 49 operati di un solo chirurgo (J Exp Orthop, ottobre 2026): spostamento del menisco a un anno 3,3 contro 3,9 mm, guarigione alla risonanza simile, miglioramento rilevante in oltre il 95% dei casi in entrambi i gruppi.", "Limiti: dati ricostruiti dalle cartelle, pochi eventi di progressione, significato clinico della differenza di mezzo millimetro incerto.\nFonte: PubMed, PMID 42857476."], "pazienti": ["Sutura della radice del menisco: buoni risultati sia dopo un esordio improvviso sia dopo uno graduale.", "In 49 persone operate, chi aveva avuto sintomi di colpo ha ottenuto punteggi un po' più alti e un'artrosi meno avanzata dopo un anno; quasi tutti sono migliorati.", "Studio piccolo, di un solo ospedale: la decisione si prende con il chirurgo.\nFonte: PubMed, PMID 42857476."]}, "instagram": {"chir": ["Radice meniscale mediale, pull-out transtibiale: esordio acuto, IKDC 73,0 contro 67,0 (p=0,02).", "49 pazienti, estrusione a un anno 3,3 contro 3,9 mm, guarigione alla RM uguale.", "Un chirurgo, dati dalle cartelle, nove eventi di progressione.\nFonte: PubMed, PMID 42857476."], "misto": ["Sutura della radice del menisco: sintomi improvvisi, risultati più alti a due anni.", "49 operati: punteggi 73 contro 67, menisco meno spostato a un anno, guarigione simile.", "Studio di un solo chirurgo, differenze piccole.\nFonte: PubMed, PMID 42857476."], "pazienti": ["Sutura del menisco: bene anche con sintomi graduali.", "In 49 persone quasi tutte sono migliorate; chi aveva sintomi improvvisi un po' di più.", "Studio piccolo: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42857476."]}, "reel": {"chir": ["Radice meniscale.", "Esordio acuto: IKDC 73,0 contro 67,0, p=0,02.", "Un chirurgo, 49 pazienti, dati dalle cartelle.\nFonte: PubMed, PMID 42857476."], "misto": ["Sutura della radice.", "Sintomi improvvisi, punteggi 73 contro 67.", "Studio piccolo, un solo chirurgo.\nFonte: PubMed, PMID 42857476."], "pazienti": ["Sutura del menisco.", "Bene anche con sintomi graduali.", "Studio piccolo: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42857476."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Menisco #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #menisco #radicemeniscale #suturameniscale #artroscopia #chirurgiaortopedica #medicinadellosport #ortopediaticino #medicinabasatasulleprove", "kw": "menisco, radice meniscale, sutura del menisco, artroscopia del ginocchio"}};
var NLB={"1": {"prof": ["Radice mediale dopo pull-out transtibiale: l'esordio acuto precede un'estrusione minore a un anno", "Coorte retrospettiva di un chirurgo (J Exp Orthop, ottobre 2026), 49 rifissazioni transtibiali di rotture di tipo 2 della radice posteriore mediale, minimo 24 mesi: IKDC finale mediano 73,0 contro 67,0 (p=0,02) dopo esordio acuto contro insidioso; progressione di Kellgren-Lawrence 1/28 contro 8/21 (p<0,01); estrusione a un anno 3,3 contro 3,9 mm (differenza 0,4 mm, IC 95% 0,1-0,7), con guarigione alla RM sovrapponibile.", "Nota critica: nove eventi di progressione rendono instabile l'OR aggiustato (0,02; IC 95% 0,001-0,35), la differenza di estrusione è di 0,3-0,4 mm senza soglia clinica validata e l'esordio è ricostruito dalle cartelle."], "mix": ["Radice del menisco: chi ha avuto un esordio improvviso sta meglio a un anno dalla sutura", "In 49 persone operate con la sutura della radice del menisco interno attraverso la tibia, quelle con sintomi comparsi di colpo hanno avuto punteggi più alti dopo due anni, un menisco meno spostato a un anno e un'artrosi che è progredita più di rado (1 persona su 28 contro 8 su 21). La guarigione vista alla risonanza era simile nei due gruppi, e quasi tutti hanno avuto un miglioramento clinicamente rilevante.", "Nota sul limite: è uno studio di un solo chirurgo, ricostruito dalle cartelle, con poche persone; la differenza di spostamento del menisco è di mezzo millimetro e il suo significato clinico resta incerto."], "paz": ["Sutura della radice del menisco: i risultati sono buoni sia con sintomi improvvisi sia graduali", "In uno studio su 49 persone operate di sutura della radice del menisco interno, quasi tutte hanno avuto un miglioramento importante a due anni. Chi aveva avuto sintomi comparsi di colpo ha ottenuto punteggi un po' più alti e, dopo un anno, un'artrosi meno avanzata.", "Lo studio è piccolo e di un solo ospedale: l'indicazione all'intervento si valuta caso per caso con il chirurgo."], "kw": "menisco, radice meniscale, sutura del menisco, dolore al ginocchio"}, "2": {"prof": ["Suture meniscali: tessuto, sede e densità delle suture predicono il fallimento più della morfologia", "Coorte retrospettiva multicentrica (J Exp Orthop, ottobre 2026), 500 suture primarie, follow-up mediano 45 mesi: 81 reinterventi (16,2%), sopravvivenza a 5 anni 82,6%; tessuto scadente HR 2,74, sutura mediale HR 2,18, sede avascolare HR 1,89, assenza di LCA associato HR 1,67, densità di suture HR 0,71 per sutura/cm; la morfologia aggiunge poco (C di Harrell da 0,782 a 0,794).", "Nota critica: intervalli degli HR non riportati nell'abstract, qualità del tessuto giudicata dal chirurgo in sala, fallimento definito come reintervento; testo completo non letto."], "mix": ["Sutura del menisco: pesano il tessuto e la sede, più della forma della lesione", "In 500 suture del menisco seguite almeno due anni, circa una su sei ha richiesto un nuovo intervento. Il rischio dipendeva soprattutto dalla qualità del tessuto trovato in sala, dalla sede (menisco interno, zona poco vascolarizzata) e dal numero di punti, più che dal disegno della lesione; era più basso quando il crociato veniva ricostruito nello stesso tempo.", "Nota sul limite: lo studio è retrospettivo, la qualità del tessuto è un giudizio del chirurgo e non sono riportati i margini di incertezza dei risultati."], "paz": ["Sutura del menisco: il tessuto conta più della forma della lesione", "Uno studio su 500 operati di sutura del menisco ha trovato che l'esito dipende soprattutto dalla qualità del menisco e dalla sua posizione, più che dalla forma dello strappo. Circa cinque su sei non hanno avuto bisogno di un nuovo intervento dopo cinque anni.", "È uno studio retrospettivo: la scelta tra suturare e non suturare si decide con il chirurgo, dopo aver visto il menisco."], "kw": "menisco, sutura meniscale, riparazione del menisco, nuovo intervento"}, "3": {"prof": ["LCA acuto: il segno della tacca femorale profonda non distingue i ginocchi con lesione dell'ALL", "Studio trasversale (J Exp Orthop, ottobre 2026), 176 LCA acuti: lesione dell'ALL alla RM in 40 (22,7%); segno della tacca profonda in 10/40 contro 29/136 (p=0,623; RR 1,17, IC 95% 0,63-2,19, calcolo nostro); traslazione tibiale anteriore uguale; unico fattore indipendente la contusione ossea (OR 2,192; IC 95% 1,012-4,748).", "Nota critica: trasversale e senza esiti di stabilità, 40 pazienti con lesione, limite inferiore dell'IC a 1,012, stato dell'ALL giudicato alla RM."], "mix": ["Crociato rotto: i segni alla risonanza non dicono se è lesa anche la struttura anterolaterale", "In 176 persone operate dopo una rottura recente del crociato, la lesione del legamento anterolaterale compariva alla risonanza in circa una su quattro. Un segno spesso associato a un trauma violento, la tacca sul femore, era presente in quote simili con e senza quella lesione (25% contro 21%), e anche lo spostamento della tibia era uguale. Solo una contusione ossea concomitante era più frequente.", "Nota sul limite: è una fotografia con la sola risonanza, senza seguire la stabilità nel tempo, e i pazienti con la lesione erano solo 40."], "paz": ["Dopo la rottura del crociato, la risonanza non basta a capire tutto del ginocchio", "In uno studio su 176 persone con rottura recente del crociato, un legamento laterale di rinforzo era lesionato in circa una su quattro, ma un segno visibile alla risonanza non permetteva di riconoscerlo con sicurezza.", "La risonanza è solo una parte della valutazione: la scelta dell'intervento dipende anche dall'esame clinico e si decide con il chirurgo."], "kw": "legamento crociato anteriore, risonanza magnetica, instabilità del ginocchio, legamento anterolaterale"}, "4": {"prof": ["Un unico trapianto di retto femorale per LCA e collaterale mediale: nota tecnica senza pazienti", "Nota tecnica (Arthrosc Tech, ottobre 2026) per la lesione acuta combinata di LCA, collaterale mediale e legamento obliquo posteriore: ricostruzione continua LCA-LCM per via artroscopica con un solo retto femorale, allograft per l'obliquo posteriore; gli autori dichiarano un solo prelievo, hamstring risparmiati e minor rischio di convergenza dei tunnel.", "Nota critica: livello V, nessun paziente e nessun esito; le proprietà elencate sono affermazioni, non misure."], "mix": ["Un solo tendine della coscia per ricostruire due legamenti del ginocchio: descrizione di una tecnica", "Un gruppo francese descrive come ricostruire insieme il crociato anteriore e il legamento interno del ginocchio usando un solo tendine prelevato dal muscolo retto femorale, aggiungendo un legamento di donatore per la parte posteriore e interna. Il vantaggio dichiarato è non dover prelevare altri tendini.", "Nota sul limite: è la descrizione di una tecnica senza pazienti operati né risultati, quindi non si sa ancora quanto funzioni."], "paz": ["Una tecnica per ricostruire due legamenti del ginocchio con un solo tendine", "Chirurghi francesi descrivono un modo di ricostruire insieme due legamenti del ginocchio usando un solo tendine del muscolo della coscia. Lo scopo è ridurre i prelievi.", "È solo la descrizione di una tecnica, senza risultati su pazienti: la scelta dell'intervento si fa con il chirurgo."], "kw": "legamento crociato anteriore, legamento collaterale mediale, lesione multilegamentosa, ricostruzione"}, "5": {"prof": ["Lemaire modificato in tunnel: creare prima il tunnel del rinforzo evita l'interferenza con il LCA", "Nota tecnica (Arthrosc Tech, ottobre 2026): tunnel femorale del rinforzo laterale scavato per primo, pin passa-fili lasciato in sede durante il tunnel del LCA sotto fluoroscopia, poi rimosso dopo conferma artroscopica; passaggio posteriore al collaterale laterale, ancora SwiveLock a gamba in rotazione interna.", "Nota critica: livello V, nessun paziente, nessuna misura della convergenza prima e dopo; vale solo per i costrutti con tunnel femorale del rinforzo."], "mix": ["Rinforzo laterale del ginocchio con il crociato: un'accortezza tecnica per non far incrociare i tunnel", "Un gruppo giapponese descrive un ordine delle manovre per eseguire insieme la ricostruzione del crociato e un rinforzo sul lato esterno del ginocchio: il canale per il rinforzo si scava per primo, e un filo guida lo tiene segnalato mentre si prepara il canale del crociato, così i due non si incontrano.", "Nota sul limite: è la descrizione di una tecnica, senza pazienti né risultati misurati."], "paz": ["Una tecnica per evitare che due canali nel femore si incrocino durante l'operazione al crociato", "Chirurghi giapponesi descrivono un ordine delle fasi dell'intervento che serve a tenere separati due canali scavati nel femore quando al crociato si aggiunge un rinforzo laterale.", "È solo la descrizione di una tecnica, senza risultati su pazienti: l'indicazione si discute con il chirurgo."], "kw": "legamento crociato anteriore, rinforzo laterale, tecnica chirurgica, instabilità del ginocchio"}, "6": {"prof": ["Osteotomia di riduzione dello slope: un abaco stima l'altezza del cuneo anteriore con errore sotto 1 mm", "Simulazione radiografica (J Exp Orthop, ottobre 2026) su 259 radiografie laterali: errore medio assoluto 0,45 ± 0,41 mm (IC 95% 0,40-0,50) sopra la tuberosità e 0,88 ± 0,79 mm (IC 95% 0,78-0,98) sotto, inferiore ai metodi a rapporto fisso e a profondità, con correzione fissa di 10°.", "Nota critica: prestazione in-sample, nessuna validazione esterna né intraoperatoria, nessun esito clinico, 194 uomini contro 65 donne."], "mix": ["Correggere la pendenza della tibia: un abaco aiuta a pianificare il cuneo da togliere", "Un gruppo di Marsiglia ha messo a punto una tabella che stima, partendo dal filo guida, quanto osso togliere davanti alla tibia per ridurre la pendenza del piatto tibiale, e l'ha provata su 259 radiografie del ginocchio. L'errore medio è stato di meno di un millimetro, e minore che con gli altri metodi provati.", "Nota sul limite: la prova è una simulazione sulle radiografie e non su pazienti operati: serve una verifica indipendente prima dell'uso in sala."], "paz": ["Una tabella per pianificare con precisione la correzione della pendenza della tibia", "Un gruppo francese ha costruito uno strumento di calcolo per pianificare un intervento che corregge la pendenza della tibia, provandolo su radiografie.", "Lo strumento non è ancora provato su pazienti operati: la pianificazione resta compito del chirurgo."], "kw": "osteotomia tibiale, pendenza tibiale, slope, legamento crociato"}, "7": {"prof": ["Prelievo rotuleo per il LCA: un difetto patellare relativo più corto si associa a KOOS migliori a un anno", "Serie retrospettiva (Arthroscopy, ottobre 2026), 23 LCA con tendine rotuleo: lunghezza relativa del difetto a 6 settimane e KOOS a un anno, attività quotidiane R=0,481 (p=0,002), sport R=0,436 (p=0,002), inginocchiarsi R=0,278 (p=0,020); larghezza e profondità del difetto non associate.", "Nota critica: 23 pazienti, p non coerenti con il numero dei partecipanti (calcolo nostro), correlazioni non aggiustate, innesto diverso dal retto femorale."], "mix": ["Dopo il prelievo del tendine rotuleo, la dimensione del difetto nella rotula si lega ai punteggi", "In 23 giovani operati di crociato con il tendine rotuleo, chi aveva un difetto più corto nella rotula, misurato alla risonanza dopo sei settimane, riferiva a un anno punteggi migliori nelle attività quotidiane e nello sport, e meno difficoltà a inginocchiarsi.", "Nota sul limite: pochi pazienti, i valori statistici riportati non sembrano coerenti con quel numero, e riguarda un solo tipo di innesto."], "paz": ["Dopo l'innesto dal tendine rotuleo, la dimensione del difetto nella rotula conta per i risultati", "In uno studio su 23 giovani operati di crociato con il tendine della rotula, un difetto più corto nell'osso della rotula si associava a punteggi migliori a un anno.", "Sono pochi pazienti e un solo tipo di innesto: la scelta si discute con il chirurgo."], "kw": "legamento crociato anteriore, tendine rotuleo, prelievo dell'innesto, dolore anteriore"}, "8": {"prof": ["Terapia estrogenica e rottura del LCA a 40-55 anni: OR 1,26 su 384.582 persone, dati assicurativi", "Coorte retrospettiva su MerativeMarketScan (JB JS Open Access, ottobre 2026), donne 40-55 anni, 16.751 in terapia, abbinamento per propensione 5:1: rottura del LCA OR 1,26 (IC 95% 1,02-1,55), ricostruzione OR 1,5 (IC 95% 1,07-2,11); incidenza bimodale con picchi a 16-20 e 40-50 anni.", "Nota critica: eventi da codici di sinistro, esposizione = prescrizione, nessun dato su dose, durata, sport; limiti inferiori degli IC a 1,02 e 1,07; associazione, non causalità."], "mix": ["Rottura del crociato a mezza età: una associazione con la terapia ormonale, da leggere con prudenza", "In una grande banca dati assicurativa americana, le donne tra 40 e 55 anni che assumevano estrogeni avevano una probabilità un po' maggiore di rottura del crociato (rapporto 1,26, intervallo 1,02-1,55) rispetto a quelle simili che non li assumevano. La rottura del crociato nelle donne ha due picchi di frequenza: a 16-20 anni e a 40-50.", "Nota sul limite: i dati vengono da rimborsi assicurativi, senza informazioni su sport o dosi: non dimostrano che la terapia sia la causa."], "paz": ["Rottura del crociato a mezza età: uno studio cerca un legame con la terapia ormonale", "Uno studio su una grande banca dati americana ha trovato che le donne tra 40 e 55 anni in terapia ormonale avevano una rottura del crociato leggermente più frequente. Non è dimostrato che la terapia ne sia la causa.", "Il dato non giustifica di modificare da soli una terapia: se ne parla con il medico curante."], "kw": "legamento crociato anteriore, donne, menopausa, rottura del crociato"}, "9": {"prof": ["UKA mediale robotica contro Oxford: hazard di revisione ridotto del 78% (p=0,046), con coorti non contemporanee", "Coorte retrospettiva da database prospettico (Bone Jt Open, ottobre 2026), Brisbane 2002-2024: Stryker Restoris MCK robotica contro Oxford cementata, rischio di revisione per qualsiasi causa -78% (p=0,046; IC non riportato), degenza -2,2 giorni (IC 95% 1,0-3,3), infezioni senza differenze (p=0,845 e 0,415).", "Nota critica: p a ridosso della soglia, numeri di eventi non riportati, robot e impianto cambiano insieme, coorti di epoche diverse; «opzione di scelta» va oltre i dati."], "mix": ["Protesi monocompartimentale: con il robot meno revisioni, ma i due gruppi sono di epoche diverse", "In uno studio australiano con dati dal 2002 al 2024, i pazienti operati con la protesi monocompartimentale robotica avevano meno nuovi interventi per qualsiasi causa rispetto a quelli con la protesi Oxford tradizionale (rischio ridotto del 78%) e restavano in ospedale 2,2 giorni in meno. Infezioni e durata dell'intervento erano simili.", "Nota sul limite: le due serie di pazienti non sono contemporanee, impianto e robot cambiano insieme, e il numero di nuovi interventi non è riportato."], "paz": ["Protesi parziale di ginocchio: uno studio confronta l'intervento con il robot e quello tradizionale", "Uno studio australiano ha confrontato due modi di mettere una protesi parziale al ginocchio: con un braccio robotico e in modo tradizionale. Con il robot c'erano meno nuovi interventi e meno giorni in ospedale.", "I due gruppi non sono dello stesso periodo, quindi il confronto ha limiti: la scelta si decide con il chirurgo."], "kw": "protesi monocompartimentale, protesi di ginocchio, chirurgia robotica, revisione"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Radice meniscale: dopo la pull-out transtibiale l'esordio acuto va meglio dell'insidioso",v:"Coorte retrospettiva di un solo chirurgo (Guangzhou): 49 rifissazioni transtibiali pull-out di rotture di tipo 2 della radice posteriore del menisco mediale, minimo 24 mesi; esordio acuto (28) contro insidioso (21). IKDC finale, mediana 73,0 (IQR 66,8-79,0) contro 67,0 (62,0-69,0), p=0,02; progressione di Kellgren-Lawrence 1/28 (3,6%) contro 8/21 (38,1%), p<0,01. Dopo aggiustamento: IKDC +6,8 punti (IC 95% 1,5-12,2), estrusione a un anno -0,32 mm (IC 95% da -0,55 a -0,08). Guarigione alla RM senza differenza; entrambi i gruppi superano la MCID (96,4% e 95,2%).",ax:"Zhang, Guo, Xu, Zhu, Luo, Wang, Jiang, He, Li",date:"ott 2026",meta:"coorte retrospettiva monocentrica, 49 pazienti, pull-out transtibiale della radice mediale, 24 mesi · [coorte retrospettiva, un solo chirurgo]",pmid:'42857476',doi:'10.1002/jeo2.70948',journal:"Journal of experimental orthopaedics",authors:"Zhang ZZ, Guo SY, Xu WN, Zhu JH, Luo JL, Wang JS, Jiang C, He B, Li WP",design:"Coorte retrospettiva monocentrica (Sun Yat-sen Memorial Hospital, Guangzhou), un chirurgo senior, 2022-2023: 82 pazienti esaminati, 49 inclusi con rottura di tipo 2 di LaPrade della radice posteriore mediale riparata con sutura transtibiale pull-out (1-2 tunnel, suture cinch o Mason-Allen modificato), pie-crusting del collaterale mediale in tutti, 6 settimane senza carico. Esclusi follow-up sotto 24 mesi, osteotomia o chirurgia legamentosa associate, artrosi K-L 3 o più. Esordio (acuto: evento di carico chiaro; insidioso: graduale) classificato da due chirurghi sulle cartelle. Esito primario IKDC finale; RM e radiografie a 12 mesi, clinica a 24. Testo completo letto (PMC)",pop:"49 pazienti (28 acuti, 21 insidiosi); età mediana 57,5 (52,5-60,0) e 56,0 (52,0-62,0) anni; donne 71,4% e 76,2%; HKA 2,9° e 2,7°; slope tibiale 6,5° e 6,3°; durata mediana dei sintomi 3 mesi in entrambi; indicazione: età ≤70 anni, artrosi K-L ≤2, varismo HKA ≤10°. Gruppi senza differenze al basale.",results:"IKDC finale: 73,0 (IQR 66,8-79,0) contro 67,0 (62,0-69,0), p=0,02; Lysholm 76,0 (73,0-78,0) contro 71,0 (70,0-74,0), p<0,01. Aggiustato: IKDC +6,8 (IC 95% 1,5-12,2), Lysholm +2,5 (IC 95% 0,4-4,6). Estrusione a un anno 3,3 (2,9-3,5) contro 3,9 (3,1-4,0) mm, differenza 0,4 mm (IC 95% 0,1-0,7); aggiustata -0,32 mm (IC 95% da -0,55 a -0,08). Progressione K-L 1/28 (3,6%) contro 8/21 (38,1%), p<0,01; OR aggiustato 0,02 (IC 95% 0,001-0,35) su 9 eventi, instabile. Guarigione alla RM completa 24/28 contro 16/21, p=0,47. MCID raggiunta da oltre il 92% in entrambi i gruppi",concl:"Gli autori: l'esordio acuto si associa a risultati funzionali e radiologici migliori dopo la pull-out transtibiale, a guarigione sovrapponibile; l'esordio può dare un'informazione prognostica preoperatoria, da non usare come indicazione isolata a operare o no, e da confermare in studi prospettici. La rilevanza clinica della piccola differenza di estrusione resta incerta.",limits:"Retrospettivo, un chirurgo e un'istituzione, classificazione dell'esordio ricostruita dalle cartelle (errore di classificazione e di memoria possibili) · 9 eventi di progressione K-L: l'OR aggiustato non è affidabile · RM e radiografie a un anno, clinica a 24 mesi: progressione tardiva non vista · differenza di estrusione 0,3-0,4 mm, senza soglia clinica validata · nessun gruppo non operato né centralizzazione.",perte:"È la tua tecnica (radice mediale, transtibiale pull-out). Non dice che l'esordio insidioso controindichi la sutura: oltre il 92% supera la MCID in entrambi i gruppi. Dice che a un anno, con guarigione alla RM identica, l'estrusione cresce di più (0,7 contro 0,4 mm) e l'artrosi progredisce più spesso dopo esordio graduale: radice «guarita» non vuol dire menisco in posizione, e questo muove la tua T3. Cosa fare: nel colloquio preoperatorio annota se l'esordio è stato acuto o graduale, come indicatore prognostico e non come criterio di esclusione."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Sutura meniscale: la forma della lesione conta meno del tessuto e della sede",v:"Coorte retrospettiva multicentrica su 500 suture meniscali artroscopiche primarie consecutive (Buenos Aires), follow-up minimo 24 mesi, mediana 45: 81 reinterventi (16,2%), sopravvivenza a 5 anni 82,6%. Dopo aggiustamento la morfologia non è un predittore indipendente (log-rank non aggiustato p=0,012); lo sono sutura mediale (HR 2,18), qualità del tessuto scadente (HR 2,74), sede avascolare (HR 1,89), densità di suture (HR 0,71 per sutura/cm) e assenza di LCA ricostruito nello stesso tempo (HR 1,67). Aggiungere la morfologia al modello porta la C di Harrell da 0,782 a 0,794. Intervalli di confidenza degli HR non riportati nell'abstract.",ax:"Rivarola, Collazo, Palanconi, Meninato, Peñaherrera-Carrillo, Barros Castro, Endara Urresta",date:"ott 2026",meta:"coorte retrospettiva multicentrica, 500 suture meniscali, follow-up ≥24 mesi (mediana 45) · [coorte retrospettiva, reintervento come esito]",pmid:'42857855',doi:'10.1002/jeo2.70947',journal:"Journal of experimental orthopaedics",authors:"Rivarola H, Collazo C, Palanconi M, Meninato M, Peñaherrera-Carrillo C, Barros Castro A, Endara Urresta F",design:"Coorte retrospettiva multicentrica (Hospital Universitario Austral, Buenos Aires) di suture meniscali artroscopiche primarie consecutive, follow-up minimo 24 mesi: tutte le morfologie riparabili, esclusi revisioni, precedente sutura o trapianto, menisco discoide, radici degenerative con artrosi avanzata, osteotomia o artroplastica associate. Fallimento = reintervento meniscale ipsilaterale. Kaplan-Meier e Cox multivariata, con C di Harrell per il guadagno prognostico della morfologia. Numero di centri e chirurghi non riportati nell'abstract. Testo completo non letto",pop:"500 pazienti; follow-up mediano 45 mesi; 81 reinterventi (16,2%). Età, sesso, distribuzione per morfologia, tecnica (tutto dentro, dentro-fuori, ibrida) e numero di pazienti con LCA associato non riportati nell'abstract.",results:"Sopravvivenza della sutura a 5 anni 82,6%; 81/500 reinterventi (16,2%). Morfologia: differenza di sopravvivenza nell'analisi univariata (log-rank p=0,012), non più associata al fallimento dopo aggiustamento. Predittori indipendenti: sutura mediale HR 2,18; tessuto di scarsa qualità HR 2,74; sede avascolare HR 1,89; densità di suture HR 0,71 per sutura aggiuntiva/cm; assenza di LCA concomitante HR 1,67. C di Harrell 0,782 senza morfologia contro 0,794 con. Intervalli di confidenza degli HR non riportati nell'abstract.",concl:"Gli autori: la morfologia ha un valore prognostico indipendente limitato; la prognosi dipende più dal contesto biologico e meccanico del menisco riparabile che dalla configurazione della lesione, e la decisione dovrebbe passare dalla classificazione descrittiva a una valutazione contestuale (qualità del tessuto, vascolarizzazione, lateralità, fattori di sutura).",limits:"Retrospettivo: la qualità del tessuto è un giudizio intraoperatorio del chirurgo, quindi soggettivo · fallimento definito come reintervento: non vede le suture non guarite ma asintomatiche · intervalli di confidenza degli HR non riportati nell'abstract · centri e chirurghi non descritti: eterogeneità non valutabile da qui · «assenza di LCA» come predittore è un'associazione con un altro tipo di paziente, non un effetto dimostrato · testo completo non letto.",perte:"Fai suture meniscali e rifissazioni di radice, ma l'abstract non separa la radice dalle altre morfologie. Il messaggio pratico è che tessuto e sede pesano più della forma: la decisione di suturare si regge su ciò che vedi in sala, non sul nome della lesione. Sul LCA associato (HR 1,67 se assente) il dato è coerente con la letteratura ma qui resta un'associazione. Nessun cambio di tecnica."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Il segno della tacca femorale profonda non indica la lesione del legamento anterolaterale",v:"Studio trasversale (Porto) su 176 pazienti di 18-50 anni operati di LCA primario dopo lesione acuta: lesione del legamento anterolaterale alla RM in 40/176 (22,7%). Segno della tacca laterale femorale profonda (>2 mm) in 10/40 (25,0%) con lesione contro 29/136 (21,3%) senza, p=0,623; traslazione tibiale anteriore mediale e laterale senza differenze. Unico fattore indipendente: contusione ossea (OR aggiustato 2,192; IC 95% 1,012-4,748; p=0,047). Concordanza fra osservatori «sostanziale» (0,715).",ax:"Santos-Nunes, Medina-Dias, Poças, Sá, Castro, Oliveira, Serdoura, Gutierres",date:"ott 2026",meta:"studio trasversale, 176 pazienti con LCA acuto, RM del legamento anterolaterale · [livello III]",pmid:'42857852',doi:'10.1002/jeo2.70950',journal:"Journal of experimental orthopaedics",authors:"Santos-Nunes D, Medina-Dias D, Poças P, Sá P, Castro M, Oliveira P, Serdoura F, Gutierres M",design:"Studio trasversale (Unidade Local de Saúde de São João, Porto) su 176 pazienti di 18-50 anni operati di LCA primario dopo lesione acuta, stratificati per stato del legamento anterolaterale alla RM (leso o integro), letto da due osservatori indipendenti. Esiti primari: tacca laterale femorale profonda (>2 mm) e traslazione tibiale anteriore mediale e laterale; regressione logistica multivariata per i fattori associati alla lesione. Testo completo non letto",pop:"176 pazienti con rottura acuta del LCA, 18-50 anni, tutti sottoposti a ricostruzione primaria; lesione del legamento anterolaterale in 40 (22,7%), integro in 136. Sesso, età media, tempo dal trauma alla RM, sport e innesto non riportati nell'abstract.",results:"Lesione del legamento anterolaterale: 40/176 (22,7%); concordanza fra osservatori sostanziale (0,715). Tacca laterale femorale profonda: 10/40 (25,0%) contro 29/136 (21,3%), p=0,623 (RR 1,17; IC 95% 0,63-2,19; calcolo mio). Traslazione tibiale anteriore mediale e laterale senza differenze significative; sublussazione laterale maggiore della mediale. Contusione ossea unico fattore indipendente: OR aggiustato 2,192 (IC 95% 1,012-4,748; p=0,047); nessuna associazione con tempo alla RM né con la tacca laterale",concl:"Gli autori: nessuna associazione diretta fra lesione del legamento anterolaterale e segni RM di instabilità rotatoria anterolaterale; la contusione ossea è l'unico fattore indipendente. La lesione può far parte di un pattern di danno più ampio che il solo segno della tacca non coglie in modo affidabile; la sublussazione laterale maggiore della mediale suggerisce un aumento della rotazione interna tibiale nei ginocchi con LCA rotto, a prescindere dallo stato del legamento anterolaterale.",limits:"Trasversale: nessun esito di stabilità né clinico, nessun riferimento chirurgico per lo stato del legamento nell'abstract (giudizio di imaging) · soltanto 40 pazienti con lesione: l'intervallo del confronto sulla tacca va da RR 0,63 a 2,19 (calcolo mio) · limite inferiore dell'IC dell'OR sulla contusione a 1,012: stima fragile · testo completo non letto.",perte:"Fai il LET su tutti i LCA, quindi questo dato non cambia la tua indicazione. Tocca di lato la T1: due indicatori di imaging che qualcuno userebbe per scegliere a chi aggiungere il rinforzo laterale (stato del legamento anterolaterale, segno della tacca profonda) qui non coincidono. Una selezione per imaging non è sostenuta da questo lavoro; la tua scelta universale non dipende dal segno. Nessuna azione clinica."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Arthrosc Tech",h:"Un solo retto femorale per ricostruire LCA e collaterale mediale in continuità",v:"Nota tecnica (Nizza, Tolosa, Tarbes, Biarritz) per la lesione acuta combinata di LCA, collaterale mediale e legamento obliquo posteriore: un unico autotrapianto di retto femorale ricostruisce LCA e collaterale mediale in continuità per via artroscopica, con allograft per il legamento obliquo posteriore. Vantaggi dichiarati dagli autori: un solo prelievo, hamstring risparmiati, lunghezza e diametro prevedibili, minor rischio di convergenza dei tunnel. Nessun paziente, nessun esito, nessun numero: descrizione di tecnica.",ax:"Ripoll, Sonnery-Cottet V, Manchec, Martinel, Pailhe, Cavaignac",date:"ott 2026",meta:"nota tecnica, nessun paziente · [livello V]",pmid:'42857186',doi:'10.1002/atn2.70304',journal:"Arthroscopy techniques",authors:"Ripoll T, Sonnery-Cottet V, Manchec O, Martinel V, Pailhe R, Cavaignac E",design:"Nota tecnica artroscopica (livello V): ricostruzione continua di LCA e collaterale mediale con un unico autotrapianto di retto femorale, legamento obliquo posteriore con allograft, nella lesione acuta combinata dei tre. Le fasi operative non sono nell'abstract. Testo completo non letto.",pop:"Nessun paziente, nessuna casistica, nessun follow-up: è una descrizione di tecnica. Numero di casi operati dagli autori non riportato.",results:"Nessun risultato clinico o biomeccanico. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract. Le proprietà della tecnica (un solo prelievo, hamstring risparmiati, lunghezza e diametro prevedibili, minor rischio di convergenza dei tunnel) sono dichiarazioni degli autori, non misure.",concl:"Gli autori: un costrutto efficiente per la ricostruzione combinata di LCA e collaterale mediale, che evita prelievi multipli, preserva gli hamstring e riduce il rischio di convergenza dei tunnel.",limits:"Nessun dato clinico: l'efficienza dichiarata non è misurata · una sola combinazione di lesioni (acuta, con legamento obliquo posteriore) · tensione e comportamento del trapianto continuo sul lato mediale non documentati nell'abstract · testo completo non letto.",perte:"Il tuo innesto di default è il retto femorale e ricostruisci il collaterale mediale con allograft o reinserzione diretta: qui lo stesso trapianto serve per entrambi. È una tecnica descritta, non provata: nessun esito. Per te è un'idea da tenere, un'alternativa all'allograft sul versante mediale con il tuo innesto abituale; non cambia nulla finché non esistono casistiche con numeri."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Arthrosc Tech",h:"Lemaire modificato: scavare per primo il tunnel del rinforzo laterale evita la convergenza",v:"Nota tecnica (Nihon University, Tokyo) sul Lemaire modificato con fissazione in tunnel osseo: si scava per primo il tunnel femorale del rinforzo laterale e si lascia il pin passa-fili in sede mentre si fa il tunnel femorale del LCA sotto fluoroscopia, per correggere la traiettoria in tempo reale; il pin si toglie dopo conferma artroscopica che non entra nel tunnel del LCA. Rinforzo passato posteriormente al collaterale laterale e fissato con ancora SwiveLock a gamba in rotazione interna. Nessun paziente, nessun esito.",ax:"Suruga, Kozu, Yahagi, Lee, Nakanishi",date:"ott 2026",meta:"nota tecnica, nessun paziente · [livello V]",pmid:'42857577',doi:'10.1002/atn2.70297',journal:"Arthroscopy techniques",authors:"Suruga M, Kozu T, Yahagi Y, Lee H, Nakanishi K",design:"Nota tecnica (livello V) sul rinforzo extra-articolare laterale secondo il Lemaire modificato con fissazione in tunnel osseo, eseguito insieme alla ricostruzione del LCA nelle revisioni e nei primari ad alto rischio. Sequenza: tunnel femorale del rinforzo, pin passa-fili lasciato in sede, tunnel femorale del LCA sotto fluoroscopia, conferma artroscopica, rimozione del pin con sutura-navetta, ricostruzione del LCA come d'abitudine, passaggio del rinforzo posteriormente al collaterale laterale, ancora SwiveLock. Testo completo non letto.",pop:"Nessun paziente, nessun follow-up: descrizione di tecnica. Innesto del LCA e numero di casi non riportati nell'abstract.",results:"Nessun risultato clinico o radiologico. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract. La riduzione dell'interferenza fra i tunnel è un'affermazione degli autori, non una misura; la tecnica non richiede strumenti speciali e si applica anche alla ricostruzione del legamento anterolaterale.",concl:"Gli autori: una soluzione pratica per ridurre l'interferenza fra i tunnel femorali e proteggere il trapianto del LCA nelle procedure combinate.",limits:"Nessun dato: la convergenza dei tunnel non è stata misurata prima e dopo · vale per i costrutti con tunnel femorale del rinforzo · tecnica non confrontata con altre soluzioni · testo completo non letto.",perte:"Tocca la T2 (il tuo costrutto non è quello studiato): è un'altra famiglia ancora, tunnel osseo con ancora e passaggio posteriore al collaterale laterale, mentre tu fissi onlay e di norma passi superficiale (a volte in profondità). La convergenza dei tunnel è un problema del rinforzo in tunnel femorale; con l'onlay non c'è tunnel del rinforzo, quindi per la tua tecnica il problema non si pone. Nessuna azione."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Osteotomia che riduce lo slope: un abaco stima il cuneo anteriore con errore sotto un millimetro",v:"Studio di simulazione radiografica (Marsiglia, con Dejour) su 259 radiografie laterali di pazienti operati di LCA: osteotomie di riduzione dello slope simulate con correzione di 10°, sopra e sotto la tuberosità. L'abaco basato su lunghezza e orientamento normalizzato del pin guida stima l'altezza del cuneo anteriore con errore medio assoluto 0,45 ± 0,41 mm (IC 95% 0,40-0,50) sopra e 0,88 ± 0,79 mm (IC 95% 0,78-0,98) sotto la tuberosità, meno dei metodi a rapporto fisso e a profondità. Prestazione in-sample con validazione incrociata; nessun esito clinico.",ax:"Plassard, Patel, Jacquet, Dejour, Piercecchi, Ollivier",date:"ott 2026",meta:"studio di simulazione radiografica, 259 radiografie, nessun esito clinico · [livello IV]",pmid:'42857856',doi:'10.1002/jeo2.70951',journal:"Journal of experimental orthopaedics",authors:"Plassard T, Patel R, Jacquet C, Dejour D, Piercecchi A, Ollivier M",design:"Studio monocentrico di sviluppo di un modello e simulazione radiografica (APHM, Marsiglia): 259 radiografie laterali strette, calibrate, di pazienti candidati a ricostruzione del LCA, con osteotomie di riduzione dello slope simulate (correzione standard di 10°) sopra e sotto la tuberosità tibiale. Tre modelli a confronto: trigonometrico con angoli normalizzati, a rapporto fisso e a profondità di osteotomia; accuratezza come errore medio assoluto e 90° percentile rispetto alle misure radiografiche, in-sample e con validazione incrociata leave-one-out e a cinque pieghe. Livello IV dichiarato. Testo completo non letto.",pop:"259 radiografie (194 uomini, 65 donne) di pazienti operati di ricostruzione del LCA; nessun paziente osteotomizzato. Angoli medi del pin guida 67,4° ± 6,0° (sopra la tuberosità) e 110,6° ± 4,7° (sotto).",results:"Errore medio assoluto del modello normalizzato: 0,45 ± 0,41 mm (IC 95% 0,40-0,50) sopra la tuberosità e 0,88 ± 0,79 mm (IC 95% 0,78-0,98) sotto; 90° percentile 0,91 e 1,77 mm; bias di Bland-Altman -0,17 e -0,06 mm, inferiori ai due modelli di confronto. Errore non influenzato da sesso né da slope di partenza, ma con potenza limitata per le differenze nelle donne (dichiarato dagli autori).",concl:"Gli autori: un abaco paziente-specifico basato su lunghezza e orientamento normalizzato del pin guida dà errori di approssimazione bassi nella simulazione, senza calibrazione radiografica intraoperatoria; i risultati sono esplorativi e in-sample, servono validazione indipendente e clinica, anche intraoperatoria, prima dell'uso.",limits:"Simulazione su radiografie con correzione fissa di 10°: non è l'intervento · prestazione in-sample, convalida incrociata sulla stessa coorte, nessuna validazione esterna · nessun esito clinico né paziente osteotomizzato · squilibrio di sesso (194 contro 65) · testo completo non letto.",perte:"Fai osteotomie correttive, comprese quelle di slope: è uno strumento di pianificazione dell'osteotomia tibiale anteriore di chiusura a cuneo, non una tecnica nuova. Gli autori stessi chiedono validazione clinica prima di qualunque uso in sala. Nessuna azione oggi; utile da conoscere quando pianifichi una riduzione di slope."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Arthroscopy",h:"Dopo prelievo rotuleo, un difetto patellare più corto si lega a punteggi migliori a un anno",v:"Serie retrospettiva (Stanford, 7 chirurghi) di 23 pazienti (15 uomini, 25,5 ± 5,2 anni) operati di LCA con tendine rotuleo (osso-tendine-osso): una lunghezza relativa minore del difetto rotuleo alla RM a 6 settimane si associa a KOOS migliori a un anno per attività quotidiane (R=0,481; p=0,002) e sport (R=0,436; p=0,002); inginocchiarsi è più difficile con difetti più lunghi (R=0,278; p=0,020). Larghezza e profondità del difetto diminuiscono da 6 settimane a un anno (p<0,001), la lunghezza no. Intervalli di confidenza non riportati nell'abstract.",ax:"Schroeder, Williams, Koltsov, Wadsworth, Nelson, Chu",date:"ott 2026",meta:"serie retrospettiva, 23 pazienti, LCA con tendine rotuleo, RM a 6 settimane e un anno · [livello IV]",pmid:'42860827',doi:'10.1002/arj.70618',journal:"Arthroscopy : the journal of arthroscopic & related surgery : official publication of the Arthroscopy Association of North America and the International Arthroscopy Association",authors:"Schroeder GG, Williams AA, Koltsov JCB, Wadsworth ALC, Nelson BJ, Chu CR (un ulteriore autore ha il record vuoto nei metadati PubMed)",design:"Serie di casi retrospettiva di livello IV dichiarato (Stanford, Palo Alto VA, Minnesota): pazienti operati da uno di 7 chirurghi tra giugno 2020 e giugno 2023 con autotrapianto rotuleo osso-tendine-osso, reclutati per una RM a 6 settimane e a un anno e per un KOOS a un anno. Dimensioni del difetto patellare osseo (lunghezza, larghezza, profondità) misurate sulla RM e rapportate a quelle della rotula, poi associate al KOOS. Affidabilità intra-osservatore buona-ottima. Testo completo non letto.",pop:"23 pazienti analizzati (15 uomini), età 25,5 ± 5,2 anni, 7 chirurghi. Sport, protocollo riabilitativo e dimensione degli innesti non riportati nell'abstract.",results:"Lunghezza relativa del difetto a 6 settimane contro KOOS a un anno: attività quotidiane R=0,481 (p=0,002), sport e tempo libero R=0,436 (p=0,002); dolore R=0,196 (p=0,078) e qualità di vita R=0,222 (p=0,054) senza significatività; difficoltà nell'inginocchiarsi R=0,278 (p=0,020). Associazioni non modificate da età e sesso. Larghezza e profondità del difetto a 6 settimane e a un anno non associate ai KOOS. Larghezza e profondità diminuiscono da 6 settimane a un anno (p<0,001), la lunghezza no. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: un difetto rotuleo relativo più corto dopo prelievo BTB si associa a PROM migliori a un anno, quindi la dimensione individuale della rotula andrebbe considerata nel prelievo.",limits:"Ventitré pazienti: i p riportati non tornano con il numero dei partecipanti (con R=0,481 su 23 persone il p atteso è circa 0,02, non 0,002; con R=0,196 il p=0,078 richiederebbe circa 80 osservazioni; calcolo mio dai dati dell'abstract): l'unità di analisi (pazienti o altro) non è chiara · correlazioni, non confronti · associazione non aggiustata per innesto, riabilitazione, sport · un solo tempo di PROM a un anno · testo completo non letto.",perte:"Non è il tuo innesto (osso-tendine-osso rotuleo; tu usi retto femorale o quadricipitale), quindi non trasferibile. L'unico messaggio generale è che il sito donatore rotuleo lascia un difetto osseo misurabile che si lega ai punteggi; con il tuo innesto abituale la questione non si pone in questa forma."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"JB JS Open Access",h:"Terapia ormonale e rottura del LCA nelle donne di mezza età: OR 1,26 su dati assicurativi",v:"Coorte retrospettiva su un database assicurativo statunitense (MerativeMarketScan, 2019-2023): 384.582 persone incluse, 16.751 in terapia estrogenica sistemica; donne di 40-55 anni, abbinamento per punteggio di propensione 5:1. Rischio di rottura del LCA nelle esposte OR 1,26 (IC 95% 1,02-1,55); di ricostruzione del LCA OR 1,5 (IC 95% 1,07-2,11). Nelle donne l'incidenza ha due picchi, a 16-20 e a 40-50 anni.",ax:"Playter, Gordon, Matzkin",date:"ott 2026",meta:"coorte retrospettiva su database assicurativo, 384.582 persone, donne 40-55 anni · [livello III]",pmid:'42857804',doi:'10.2106/JBJS.OA.26.00279',journal:"JB & JS open access",authors:"Playter KP, Gordon OL, Matzkin EG",design:"Coorte retrospettiva (New England Baptist Hospital, Brigham and Women's Hospital) sul database MerativeMarketScan Commercial: donne di 40-55 anni con sinistri tra il 1° gennaio 2019 e il 31 dicembre 2023; esposizione = qualunque estrogeno sistemico supplementare; esito = qualsiasi rottura del LCA dopo la data indice; abbinamento per punteggio di propensione 5:1 per il più vicino vicino, regressione logistica condizionata aggiustata per età, comorbilità e stato peri- o postmenopausale. Livello III dichiarato. Testo completo non letto.",pop:"384.582 persone incluse, 16.751 in terapia ormonale; donne 40-55 anni con copertura commerciale. Dose, via di somministrazione, durata della terapia, livello di sport e tipo di trauma non riportati nell'abstract.",results:"Rottura del LCA: OR 1,26 (IC 95% 1,02-1,55) nelle donne in terapia contro le abbinate; ricostruzione del LCA: OR 1,5 (IC 95% 1,07-2,11). Incidenza per persona-tempo bimodale nelle donne, con picchi a 16-20 e a 40-50 anni. Numeri di eventi nei due gruppi non riportati nell'abstract.",concl:"Gli autori: la terapia ormonale a base di estrogeni si associa a un rischio maggiore di rottura del LCA, a parità di età, comorbilità e stato menopausale; la relazione è verosimilmente multifattoriale e servono studi prospettici.",limits:"Database assicurativo: la rottura è un codice di sinistro, non una diagnosi verificata · l'esposizione è la prescrizione, non l'assunzione · nessun dato su sport, dose, durata, trauma: confondenti non misurabili · limite inferiore dell'IC dell'OR sulla rottura a 1,02, fragile · numeri di eventi non riportati nell'abstract · associazione, non causalità · testo completo non letto.",perte:"Fuori dalla tua tecnica: tocca la prevenzione e la lettura epidemiologica della rottura del LCA nelle donne tra 40 e 55 anni. Il dato è un'associazione su sinistri assicurativi, non dimostra che gli estrogeni causino la rottura; la terapia può essere un marcatore di altro (menopausa, attività). Non cambia nulla nell'indicazione chirurgica."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Bone Jt Open",h:"Protesi monocompartimentale robotica contro Oxford: meno revisioni, ma coorti non contemporanee",v:"Coorte retrospettiva su database prospettico (Brisbane, 2002-2024): UKA mediale robotica con impianto Stryker Restoris MCK contro Oxford cementata convenzionale, minimo 6 mesi. Rischio di revisione per qualsiasi causa ridotto del 78% nel gruppo robotico (p=0,046; intervallo di confidenza non riportato nell'abstract); degenza più breve di 2,2 giorni (IC 95% 1,0-3,3); durata dell'intervento (p=0,733), infezione superficiale (p=0,845) e infezione periprotesica (p=0,415) senza differenze. Numeri di pazienti e di revisioni non riportati nell'abstract.",ax:"Cheok, Law, Vermeir, Jaarsma, Doornberg, Silva",date:"ott 2026",meta:"coorte retrospettiva da database prospettico, UKA mediale robotica contro Oxford · [livello III per disegno, coorti non contemporanee]",pmid:'42863833',doi:'10.1302/2633-1462.710.BJO-2026-0104.R1',journal:"Bone & joint open",authors:"Cheok T, Law K, Vermeir JF, Jaarsma RL, Doornberg JN, Silva AM",design:"Analisi retrospettiva di un database prospettico (The Prince Charles Hospital, Brisbane), gennaio 2002-dicembre 2024: UKA mediale robotica con Stryker Restoris MCK contro UKA convenzionale cementata Oxford, minimo 6 mesi di follow-up, selezione secondo Kozinn e Scott. Esito primario: rivalutazione per qualsiasi causa; secondari: degenza, durata, infezione superficiale e periprotesica; aggiustamento per età, sesso, IMC, ASA, Charlson e grado del chirurgo. Il robot non è nominato nell'abstract. Testo completo non letto.",pop:"Pazienti con gonartrosi mediale isolata selezionata, operati dal 2002 al 2024; numeri per gruppo, età e follow-up mediano non riportati nell'abstract.",results:"Rischio di revisione per qualsiasi causa: riduzione del 78% con la robotica (p=0,046; intervallo non riportato nell'abstract). Degenza: -2,2 giorni (IC 95% 1,0-3,3; p<0,001). Durata dell'intervento p=0,733; infezione superficiale p=0,845; infezione periprotesica p=0,415. Numero di revisioni per gruppo non riportato nell'abstract.",concl:"Gli autori: il miglioramento sostanziale della revisione suggerisce che la UKA robotica sia l'opzione di scelta nell'artrosi mediale isolata, in pazienti selezionati e soprattutto con chirurghi a basso volume; la degenza più breve va letta con cautela per la non contemporaneità delle coorti.",limits:"p=0,046 a ridosso della soglia e senza intervallo · coorti non contemporanee (lo dicono gli autori): epoca, impianto, curva di apprendimento e robot cambiano insieme, non si isola l'effetto del robot · numeri di eventi non riportati: impossibile valutare la potenza · «opzione di scelta» va oltre i dati · testo completo non letto.",perte:"Fai UKA, ma la tua robotica è VELYS sulla protesi totale; qui impianto Stryker contro Oxford: due variabili cambiate insieme, in epoche diverse. Non trasferibile alla tua protesi totale robotica, e non tocca il tuo impianto monocompartimentale se diverso. Nessuna azione."}];
var SUGGQ=[{"k": "kol", "n": "Thomas Ripoll (Clinique Saint George, Nizza, Francia)", "w": "Francia: primo autore della nota tecnica di oggi sulla ricostruzione continua di LCA e collaterale mediale con un solo retto femorale (PMID 42857186; afferenza letta nei metadati PubMed). Corrispondenza tecnica diretta con il tuo innesto di default (retto femorale) e con la tua ricostruzione del collaterale mediale. Sostituisce Andrea Baldini (11 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Martedì 13 ottobre. Il briefing di ieri non è stato pubblicato: la ricerca di oggi copre anche lunedì. Oggi nove lavori, nessuna scheda rossa e nessuna arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida nella tua pratica. Il lavoro del giorno riguarda una tua tecnica: una coorte retrospettiva di Guangzhou, di un solo chirurgo, su quarantanove rifissazioni transtibiali pull-out della radice posteriore del menisco mediale. Chi aveva avuto un esordio improvviso ha ottenuto a due anni un IKDC mediano di settantatré contro sessantasette, e l'artrosi è progredita in un caso su ventotto contro otto su ventuno. A un anno l'estrusione è maggiore dopo un esordio graduale, tre virgola nove contro tre virgola tre millimetri, ma la guarigione alla risonanza è la stessa, e oltre il novantacinque per cento di entrambi i gruppi raggiunge la differenza minima clinicamente rilevante. Limiti: esordio ricostruito dalle cartelle, nove eventi di progressione che rendono instabile il rapporto aggiustato, e una differenza di estrusione di mezzo millimetro di rilevanza incerta. Per te: annota se l'esordio è stato acuto o graduale, come indicatore e non come motivo per escludere dalla sutura. Tra le altre schede: cinquecento suture meniscali in Argentina, dove contano il tessuto, la sede e il numero di punti più della forma della lesione. Uno studio trasversale su centosettantasei crociati acuti, dove il segno della tacca femorale profonda non distingue i ginocchi con lesione del legamento anterolaterale, ma con venticinque contro ventuno per cento il confronto non esclude differenze. Due note tecniche senza pazienti: un solo retto femorale per ricostruire crociato e collaterale mediale, e un Lemaire modificato in cui si scava per primo il tunnel del rinforzo. Una simulazione su duecentocinquantanove radiografie di un abaco per l'osteotomia che riduce lo slope, con errore sotto il millimetro ma nessun paziente. Completano uno studio con ventitré pazienti sul difetto rotuleo dopo il prelievo osso-tendine-osso, i cui valori statistici non tornano con il numero dei partecipanti; un'associazione fra terapia ormonale e rottura del crociato a mezza età, con rapporto di uno virgola ventisei su dati assicurativi; e una protesi monocompartimentale robotica con meno revisioni, ma in coorti di epoche diverse. Per le proposte da seguire oggi il nome è Thomas Ripoll, di Nizza, per il retto femorale nella ricostruzione combinata.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Martedì tredici ottobre. Una nota prima di tutto: il briefing di ieri non è uscito, quindi la ricerca di oggi copre anche lunedì."}, {"chi": "B", "t": "E oggi? Qualcosa di rosso?"}, {"chi": "A", "t": "Nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo nuovo, nessuna ritrattazione che ti riguardi, nessun consensus nella tua pratica."}, {"chi": "B", "t": "Il lavoro del giorno?"}, {"chi": "A", "t": "Tocca una tua tecnica: la rifissazione transtibiale della radice posteriore del menisco mediale. Quarantanove pazienti di un solo chirurgo a Guangzhou."}, {"chi": "B", "t": "E cosa trovano?"}, {"chi": "A", "t": "Con esordio improvviso, a due anni l'IKDC mediano è settantatré contro sessantasette, e l'artrosi progredisce in un caso su ventotto contro otto su ventuno. L'estrusione a un anno è tre virgola nove contro tre virgola tre millimetri, ma la guarigione alla risonanza è la stessa."}, {"chi": "B", "t": "Quindi l'esordio graduale è un motivo per non operare?"}, {"chi": "A", "t": "No. Oltre il novantacinque per cento di entrambi i gruppi raggiunge la differenza minima rilevante. E i limiti sono pesanti: un chirurgo, esordio ricostruito dalle cartelle, nove eventi di progressione, mezzo millimetro di estrusione di significato incerto."}, {"chi": "B", "t": "Quindi per te, in concreto?"}, {"chi": "A", "t": "Annota se l'esordio è stato acuto o graduale, come indicatore prognostico. E ricorda che la radice guarita alla risonanza non vuol dire menisco in posizione."}, {"chi": "B", "t": "Le altre schede?"}, {"chi": "A", "t": "Cinquecento suture meniscali in Argentina: contano il tessuto, la sede e il numero di punti più della forma della lesione. Poi una nota tecnica con un solo retto femorale per crociato e collaterale mediale, senza pazienti."}, {"chi": "B", "t": "Il segno della tacca profonda dice qualcosa sul legamento anterolaterale?"}, {"chi": "A", "t": "Su centosettantasei crociati acuti non lo distingue, ma il confronto non esclude differenze. E per la tua scelta del rinforzo laterale su tutti i pazienti non cambia nulla. Il nome da seguire oggi è Thomas Ripoll, di Nizza, per il retto femorale nella ricostruzione combinata."}];
